package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class LabelDenylistVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property label denylist of observability config ")
  void test_label_denylist_v_o_builder() {
    Assertions.assertFalse(LabelDenylistVO.nullValue().getLabelDenylist().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(LabelDenylistVO.tryFrom(null).getLabelDenylist().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", LabelDenylistVO.from("one").getLabelDenylist().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> LabelDenylistVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", LabelDenylistVO.from("one").toString());
  }
}
